</div><script>
(function(){
  function initNileCruisePage(root){
    if(!root || root.dataset.avNileReady === '1') return;
    root.dataset.avNileReady = '1';

    var tabs = root.querySelectorAll('.tab');
    for(var i=0;i<tabs.length;i++){
      tabs[i].addEventListener('click',function(){
        var allTabs = root.querySelectorAll('.tab');
        var allPanels = root.querySelectorAll('.tab-panel');
        for(var j=0;j<allTabs.length;j++) allTabs[j].classList.remove('active');
        for(var k=0;k<allPanels.length;k++) allPanels[k].classList.remove('active');
        this.classList.add('active');
        var target = root.querySelector('#' + this.getAttribute('data-tab'));
        if(target) target.classList.add('active');
      });
    }

    var headers = root.querySelectorAll('.day-header');
    for(var h=0;h<headers.length;h++){
      headers[h].addEventListener('click',function(){
        this.parentElement.classList.toggle('open');
      });
    }

    var BASE_PRICE = 0;
    function getById(id){ return root.querySelector('#' + id); }
    function getNum(id,fallback){
      var el = getById(id);
      if(!el) return fallback;
      var v = parseInt(el.value,10);
      return isNaN(v) ? fallback : v;
    }
    function calcPrice(){
      var totalInput = getById('totalInput');
      if(BASE_PRICE <= 0){
        if(totalInput) totalInput.value = 'Price depending on availability';
        return;
      }
      var adults = getNum('adults',2);
      var children = getNum('children',0);
      var total = (adults * BASE_PRICE) + (children * Math.round(BASE_PRICE * 0.7));
      if(totalInput) totalInput.value = 'Estimated from $' + total.toLocaleString() + ' total - based on starting price';
    }
    function setCounter(type,value){
      var el = getById(type);
      if(!el) return;
      var min = parseInt(el.getAttribute('min'),10);
      var max = parseInt(el.getAttribute('max'),10);
      if(isNaN(min)) min = 0;
      if(isNaN(max)) max = 99;
      value = Math.max(min, Math.min(max, value));
      el.value = value;
      var btns = root.querySelectorAll('[data-target="' + type + '"]');
      for(var i=0;i<btns.length;i++){
        var step = parseInt(btns[i].getAttribute('data-step'),10);
        if(step < 0) btns[i].disabled = value <= min;
        if(step > 0) btns[i].disabled = value >= max;
      }
      calcPrice();
    }

    var counterBtns = root.querySelectorAll('.counter-btn');
    for(var b=0;b<counterBtns.length;b++){
      counterBtns[b].addEventListener('click',function(e){
        e.preventDefault();
        var target = this.getAttribute('data-target');
        var step = parseInt(this.getAttribute('data-step'),10);
        var current = getNum(target, target === 'adults' ? 2 : 0);
        setCounter(target, current + step);
      });
    }
    setCounter('adults', getNum('adults',2));
    setCounter('children', getNum('children',0));

    var dateInput = root.querySelector('input[name="travel_date"]');
    if(dateInput){
      var today = new Date();
      var yyyy = today.getFullYear();
      var mm = String(today.getMonth()+1).padStart(2,'0');
      var dd = String(today.getDate()).padStart(2,'0');
      dateInput.min = yyyy + '-' + mm + '-' + dd;
    }

    var form = root.querySelector('#bookingForm');
    var submitBtn = root.querySelector('#submitBtn');
    var formStatus = root.querySelector('#formStatus');
    if(form && submitBtn){
      form.addEventListener('submit',function(e){
        e.preventDefault();
        var originalText = submitBtn.innerHTML;
        submitBtn.disabled = true;
        submitBtn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> <span>Sending...</span>';
        if(formStatus){ formStatus.style.display = 'none'; formStatus.className = 'form-status'; }
        var formData = new FormData(form);
        var object = {};
        formData.forEach(function(value,key){ object[key]=value; });
        fetch('https://n8n.mfdevelopers.xyz/webhook-test/avicon-booking',{method:'POST',body:new FormData(form),keepalive:true}).catch(function(){});
        fetch('https://api.web3forms.com/submit',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(object)})
          .then(function(response){ return response.json(); })
          .then(function(result){
            if(result.success){ window.location.href='/thank-you/'; }
            else if(formStatus){ formStatus.className='form-status error'; formStatus.textContent=result.message || 'Something went wrong. Please try again or contact us via WhatsApp.'; formStatus.style.display='block'; }
          })
          .catch(function(){ if(formStatus){ formStatus.className='form-status error'; formStatus.textContent='Connection error. Please check your internet and try again.'; formStatus.style.display='block'; } })
          .then(function(){ submitBtn.disabled=false; submitBtn.innerHTML=originalText; });
      });
    }
  }

  function boot(){
    var pages = document.querySelectorAll('.av-nile-cruise-page');
    for(var i=0;i<pages.length;i++) initNileCruisePage(pages[i]);
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>
